CREATE PROCEDURE [dbo].[DCConv_LkUp_PopulateORGANIZATION_TYPE] 
	@pin_run_reference_time datetime
AS
BEGIN
 -- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DELETE FROM [dbo].[ORGANIZATION_TYPE];

	DBCC CHECKIDENT (
			'dbo.ORGANIZATION_TYPE'
			,RESEED
			,0
			);

	INSERT INTO dbo.ORGANIZATION_TYPE
	 (ORGANIZATION_TYPE_NAME, LAST_MODIFIED_DATE_TIME, LAST_MODIFIED_USER)
	SELECT DISTINCT PROVIDER_TYPE_NAME as ORGANIZATION_TYPE_NAME, 
	 CAST(0x0000A64900000000 AS DateTime) as LAST_MODIFIED_DATE_TIME, 
	 N'5c8eea1d-b312-41a7-999c-dedbcca3688d' as LAST_MODIFIED_USER
	FROM PROVIDER_TYPE 
	WHERE [PROVIDER_CATEGORY_TYPE_ID] <> 1



